  auto cta_coord = make_coord(blockIdx.x, blockIdx.y, _);
  Tensor gA = local_tile(mA, cta_tiler, cta_coord, Step<_1,X,_1>{});
  Tensor gB = local_tile(mB, cta_tiler, cta_coord, Step<X,_1,_1>{});
  Tensor gC = local_tile(mC, cta_tiler, cta_coord, Step<_1,_1,X>{});

  // Shared memory (padded row stride to avoid bank conflicts on column access)
  constexpr int kPad = 4;
  constexpr int kSmemAStride = 32 + kPad;
  constexpr int kSmemBStride = 32 + kPad;
  __shared__ TA smemA[128*kSmemAStride];
  __shared__ TB smemB[128*kSmemBStride];
  Tensor sA = make_tensor(make_smem_ptr(smemA),
                          make_layout(make_shape(Int<128>{}, Int<32>{}),
                                      make_stride(Int<kSmemAStride>{}, Int<1>{})));
  Tensor sB = make_tensor(make_smem_ptr(smemB),
                          make_layout(make_shape(Int<128>{}, Int<32>{}),
                                      make_stride(Int<kSmemBStride>{}, Int<1>{})));

  // Thread layouts
  auto tA = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tB = make_layout(make_shape(Int<32>{}, Int<8>{}));
  auto tC = make_layout(make_shape(Int<16>{}, Int<16>{}));

  Tensor tAgA = local_partition(gA, tA, threadIdx.x);
  Tensor tAsA = local_partition(sA, tA, threadIdx.x);
  Tensor tBgB = local_partition(gB, tB, threadIdx.x);
  Tensor tBsB = local_partition(sB, tB, threadIdx.x);

  Tensor tCsA = local_partition(sA, tC, threadIdx.x, Step<_1,X>{});
  Tensor tCsB = local_partition(sB, tC, threadIdx.x, Step<X,_1>{});
  Tensor tCgC = local_partition(gC, tC, threadIdx.x, Step<_1,_1>{});

  Tensor tCrC = make_tensor_like(tCgC);
  clear(tCrC);

  // Loop over K
  int K_TILE_MAX = size<2>(tAgA);
  for (int k_tile = 0; k_tile < K_TILE_MAX; ++k_tile) {
    copy(tAgA(_,_,k_tile), tAsA);
    copy(tBgB(_,_,k_tile), tBsB);

    cp_async_fence();
    cp_async_wait<0>();
    __syncthreads();

    gemm(tCsA, tCsB, tCrC);
    __syncthreads();
  }

  // Epilogue
  axpby(1.0f, tCrC, 0.0f, tCgC);
}

// Host wrapper
torch::Tensor cute_matmul(torch::Tensor A, torch::Tensor B) {
  TORCH_CHECK(A.is_cuda() && B.is_cuda(), "A and B must be CUDA tensors");
  TORCH_CHECK(A.dim()==2 && B.dim()==2,  "A and B must be 2D");
  TORCH_CHECK(A.scalar_type()==at::kFloat && B.scalar_type()==at::kFloat,
              "Expect float32 tensors");

  // A:[M,K] row-major, B:[K,N] row-major -> C = A @ B
  int M = (int)A.size(0);
  int K = (int)A.size(1);
  int N = (int)B.size(1);
  TORCH_CHECK((int)B.size(0)==K, "B.size(0) must equal K");

  TORCH_CHECK(M % 128 == 0 && N % 128 == 0 && K % 32 == 0,
              "This simple CUTE kernel requires M,N divisible by 128 and K divisible by 32");

  auto A_c = A.contiguous();
  auto B_c = B.contiguous();
  auto C   = torch::empty({M, N}, A.options());

  auto ptrA = A_c.data_ptr<float>();
  auto ptrB = B_c.data_ptr<float>();
  auto ptrC = C.data_ptr<float>();

  // A is (M,K) row-major -> stride (K,1) : direct access, no transpose trick needed.
  auto dA = make_stride(K, Int<1>{});
  // B is (K,N) row-major physically; viewed as mB shape (N,K) via stride (1,N)
  // gives mB(n,k) = B(k,n) without moving data.
  auto dB = make_stride(Int<1>{}, N);
  // C is (M,N) row-major -> stride (N,1)
  auto dC = make_stride(N, Int<1>{});

  auto shape_MNK = make_shape(M, N, K);

  dim3 dimBlock(256);
  dim3 dimGrid((M+127)/128, (N+127)/128);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  gemm_device<<<dimGrid, dimBlock, 0, stream>>>(shape_MNK, ptrA, dA, ptrB, dB, ptrC, dC);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "CUTE gemm launch failed: ", cudaGetErrorString(err));

  return C;
}
